head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00200_05.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
scwin.vArray = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.stf.showObj(grd_Excel, false);

    // 결산일자 조회

	//----W-Craft WebSquare 변환 확인: fn_SrchAcntclsDt----//
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_Div1.removeAll();
    dts_Div2.removeAll();
    dts_Div3.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsDt----//
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 배당 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }
    scwin.fn_Search1(); // 상단 그리드 조회
    scwin.fn_Search2(); // 중단 그리드 조회
    scwin.fn_Search3(); // 하단 그리드 조회

};


/**
 * 상단 조회
 */
scwin.fn_Search1 = function() {
    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_Div1);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.div1" + "&outputMessageId=FIS_DIV1" + scwin.fn_GetParam();
    dts_Div1.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Div1.Reset();
};


/**
 * 중단 조회
 */
scwin.fn_Search2 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.div2" + "&outputMessageId=FIS_DIV2" + scwin.fn_GetParam();
    dts_Div2.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Div2.Reset();
};


/**
 * 하단 조회
 */
scwin.fn_Search3 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.div3" + "&outputMessageId=FIS_DIV1" + scwin.fn_GetParam();
    dts_Div3.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_Div3.Reset();
};


/**
 * 엑셀용 데이터 조회
 */
scwin.fn_SearchExcel = function() {
    dts_Excel.removeAll();
    /*
		var url = "/listingCommon.do?SCREN_ID=" +vScrenID
                + "&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01
                + "&method=listGeneralForDynamic"
                + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp"
                + "&queryId=krx.lds.stf.fis.select.div4"
				+ "&outputMessageId=FIS_DIV2"
				+ fn_GetParam();

		dts_Excel.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
		dts_Excel.Reset();
		*/

    // 데이터셋을 복사하는 방식으로 하자.
    $c.stf.CopyDataSetHeader(dts_Div2, dts_Excel);

    // dts_Div2 Copy
    scwin.fn_AppendDataset(dts_Excel, dts_Div1);
    scwin.fn_AppendDataset(dts_Excel, dts_Div2);
    scwin.fn_AppendDataset(dts_Excel, dts_Div3);
    $c.data.downloadGridViewExcel(grd_Excel, "배당", "", "1");
};


/**
 * 데이터셋 append
 */
scwin.fn_AppendDataset = function(pDsExcel, pDsTar) {
    for (var nRow = 1; nRow <= pDsTar.CountRow; nRow++) {
        pDsExcel.AddRow();
        var nIdx = pDsExcel.RowPosition;
        pDsExcel.setCellData(nIdx, "DIV_TYP", pDsTar.getCellData(nRow, "DIV_TYP"));
        pDsExcel.setCellData(nIdx, "GUBUN", pDsTar.getCellData(nRow, "GUBUN"));
        pDsExcel.setCellData(nIdx, "DIV1", pDsTar.getCellData(nRow, "DIV1"));
        pDsExcel.setCellData(nIdx, "DIV_RT1", pDsTar.getCellData(nRow, "DIV_RT1"));
        pDsExcel.setCellData(nIdx, "DIV2", pDsTar.getCellData(nRow, "DIV2"));
        pDsExcel.setCellData(nIdx, "DIV_RT2", pDsTar.getCellData(nRow, "DIV_RT2"));
        pDsExcel.setCellData(nIdx, "DIV3", pDsTar.getCellData(nRow, "DIV3"));
        pDsExcel.setCellData(nIdx, "DIV_RT3", pDsTar.getCellData(nRow, "DIV_RT3"));
        pDsExcel.setCellData(nIdx, "DIV4", pDsTar.getCellData(nRow, "DIV4"));
        pDsExcel.setCellData(nIdx, "DIV_RT4", pDsTar.getCellData(nRow, "DIV_RT4"));
        pDsExcel.setCellData(nIdx, "DIV5", pDsTar.getCellData(nRow, "DIV5"));
        pDsExcel.setCellData(nIdx, "DIV_RT5", pDsTar.getCellData(nRow, "DIV_RT5"));
    }
};



/**
 * 파라미터 스트링 만들기
 */
scwin.fn_GetParam = function() {
    var vParam = "";
    vParam = "&param01=" + scwin.vKisCd + "&param02=" + scwin.vArray[0].VALUE + "&param03=" + scwin.vArray[1].VALUE + "&param04=" + scwin.vArray[2].VALUE + "&param05=" + scwin.vArray[3].VALUE + "&param06=" + scwin.vArray[4].VALUE;
    return vParam;
};


/**
 * 그리드 헤더의 제목을 세팅.
 */
scwin.fn_SetGrdHeaderNm = function(pArray) {
    $c.cm.setColumnProp(grd_Div1, "DIV1", "Name", pArray[0].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV2", "Name", pArray[1].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV3", "Name", pArray[2].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV4", "Name", pArray[3].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV5", "Name", pArray[4].TEXT);

    // 엑셀 다운용
    $c.cm.setColumnProp(grd_Excel, "DIV1", "Name", pArray[0].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV2", "Name", pArray[1].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV3", "Name", pArray[2].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV4", "Name", pArray[3].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV5", "Name", pArray[4].TEXT);
    scwin.vArray = pArray;
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_Div1.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    // 엑셀용 데이터 조회를 위해 쿼리 날림.
    scwin.fn_SearchExcel();
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_Div1_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_Div1);
    $c.stf.alert_error(dts_Div1);
};
scwin.dts_Div1_OnLoadCompleted = function(rowcount) {
    if (dts_Div1.errorMsg) {
        alert(dts_Div1.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_Div1);
};
scwin.dts_Excel_OnLoadCompleted = function(rowcount) {
    $c.data.downloadGridViewExcel(grd_Excel, "배당", "", "1");
};
